package dev.reckless.tvlauncher;

import android.app.Activity;import android.os.Bundle;import android.os.Build;import android.os.StatFs;import android.app.ActivityManager;import android.content.Context;import android.graphics.Color;import android.view.Gravity;import android.widget.*;import java.io.File;
public class TvHealthActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.rgb(16,21,28));sc.setPadding(dp(34),dp(24),dp(34),dp(28));LinearLayout box=new LinearLayout(this);box.setOrientation(1);sc.addView(box);setContentView(sc);
 add(box,"TV HEALTH","Read-only device information. Values are supplied by Android and may be restricted by Fire OS.");File path=getFilesDir();StatFs fs=new StatFs(path.getAbsolutePath());long total=fs.getTotalBytes(),free=fs.getAvailableBytes();add(box,"STORAGE","Available: "+fmt(free)+"\nTotal: "+fmt(total)+"\nUsed: "+fmt(total-free));ActivityManager am=(ActivityManager)getSystemService(Context.ACTIVITY_SERVICE);ActivityManager.MemoryInfo mi=new ActivityManager.MemoryInfo();am.getMemoryInfo(mi);add(box,"MEMORY","Available RAM: "+fmt(mi.availMem)+"\nTotal RAM: "+fmt(mi.totalMem)+"\nLow-memory state: "+(mi.lowMemory?"Yes":"No"));add(box,"DEVICE","Manufacturer: "+Build.MANUFACTURER+"\nModel: "+Build.MODEL+"\nDevice: "+Build.DEVICE+"\nAndroid: "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")\nBuild: "+Build.DISPLAY);add(box,"BATTERY","Battery details are not exposed consistently on all Fire TV models. Check Fire OS Settings > My Fire TV > About for device-specific diagnostics.");add(box,"BACK","Return to settings",()->finish());}
 private void add(LinearLayout box,String title,String body){TextView t=new TextView(this);t.setText(title);t.setTextColor(Color.rgb(26,174,102));t.setTextSize(12);t.setPadding(0,dp(12),0,dp(5));box.addView(t);TextView d=new TextView(this);d.setText(body);d.setTextColor(Color.WHITE);d.setTextSize(17);d.setPadding(0,0,0,dp(12));box.addView(d);}private void add(LinearLayout box,String title,String body,Runnable r){add(box,title,body);TextView t=new TextView(this);t.setText("DONE  ›");t.setTextColor(Color.WHITE);t.setTextSize(16);t.setGravity(Gravity.CENTER_VERTICAL);t.setFocusable(true);t.setPadding(dp(12),0,0,0);box.addView(t,new LinearLayout.LayoutParams(-1,dp(54)));t.setOnClickListener(v->r.run());}
 private String fmt(long n){return String.format(java.util.Locale.US,"%.2f GB",n/(1024d*1024d*1024d));}private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
}
